import math,json
m=(224,192); p=(16,32)
def calc(s,new):
 r=max(s[0]/m[0],s[1]/m[1]); d=tuple(max(1,math.floor(x/r)) if new else math.ceil(x/r) for x in s) if r>1 else s
 return tuple((x+y-1)//y*y for x,y in zip(d,p))
counts=[0,0]; changed=0
for a in range(1,301):
 for b in range(1,301):
  s=(a,b); old=calc(s,False); new=calc(s,True)
  counts[0]+=any(x>y for x,y in zip(old,m)); counts[1]+=any(x>y for x,y in zip(new,m)); changed+=old!=new
print(json.dumps({'input_pairs':90000,'overflow_old_new':counts,'changed_outputs':changed,'example':{'input':[230,1],'old':calc((230,1),False),'new':calc((230,1),True)},'thin':{'input':[10000,1],'new':calc((10000,1),True)}}))

